-- =====================================================================
-- Banco 1: lanchonete_vendas
-- Lanchonete de médio porte (dados 100% FICTÍCIOS) | MySQL 8.0
-- Conteúdo: cardápio, clientes, pedidos e itens vendidos
-- Período dos dados: 2026-04-01 a 2026-09-30
-- Pode ser executado várias vezes: ele recria o banco do zero.
-- Execute ANTES o 02_lanchonete_operacao.sql só se quiser cruzar os dois bancos
-- (pedidos.id_funcionario aponta para lanchonete_operacao.funcionarios).
-- =====================================================================

DROP DATABASE IF EXISTS lanchonete_vendas;
CREATE DATABASE lanchonete_vendas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lanchonete_vendas;

CREATE TABLE categorias (
    id_categoria  INT PRIMARY KEY,
    nome          VARCHAR(40) NOT NULL
);

CREATE TABLE produtos (
    id_produto       INT PRIMARY KEY,
    nome             VARCHAR(60)   NOT NULL,
    id_categoria     INT           NOT NULL,
    preco            DECIMAL(10,2) NOT NULL,    -- preço ATUAL de tabela
    custo            DECIMAL(10,2) NOT NULL,    -- custo ATUAL de produção
    data_lancamento  DATE          NOT NULL,
    ativo            TINYINT(1)    NOT NULL,    -- 1 = no cardápio, 0 = descontinuado
    CONSTRAINT fk_prod_cat FOREIGN KEY (id_categoria) REFERENCES categorias (id_categoria)
);

CREATE TABLE clientes (
    id_cliente     INT PRIMARY KEY,
    nome           VARCHAR(80) NOT NULL,
    email          VARCHAR(100) NULL,           -- nem todo cliente informa
    telefone       VARCHAR(20)  NULL,           -- nem todo cliente informa
    bairro         VARCHAR(50)  NOT NULL,
    data_cadastro  DATE         NOT NULL
);

CREATE TABLE pedidos (
    id_pedido        INT PRIMARY KEY,
    id_cliente       INT NULL,                  -- NULL = venda de balcão sem cadastro
    id_funcionario   INT NOT NULL,              -- atendente/caixa (tabela em lanchonete_operacao)
    data_pedido      DATETIME NOT NULL,
    canal            ENUM('balcao','delivery','app') NOT NULL,
    forma_pagamento  ENUM('pix','credito','debito','dinheiro','vale_refeicao') NOT NULL,
    status           ENUM('concluido','cancelado') NOT NULL,
    taxa_entrega     DECIMAL(10,2) NOT NULL,
    desconto         DECIMAL(10,2) NOT NULL,
    CONSTRAINT fk_ped_cli FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente),
    INDEX idx_ped_data (data_pedido)
);

CREATE TABLE itens_pedido (
    id_item         INT PRIMARY KEY,
    id_pedido       INT NOT NULL,
    id_produto      INT NOT NULL,
    quantidade      INT NOT NULL,
    preco_unitario  DECIMAL(10,2) NOT NULL,     -- preço praticado NA DATA da venda
    CONSTRAINT fk_item_ped  FOREIGN KEY (id_pedido)  REFERENCES pedidos (id_pedido),
    CONSTRAINT fk_item_prod FOREIGN KEY (id_produto) REFERENCES produtos (id_produto),
    INDEX idx_item_ped (id_pedido)
);
































































































































